contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool dummy) public payable {
        require(dummy || !dummy);
        require(!c.distributionFinished());
        require(!c.blacklist(address(this)));
        require(c.value() > 0);
        require(c.value() <= c.totalRemaining());

        uint256 v = c.value(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blackBefore = c.blacklist(address(this)); if (__ESBMC_reverted()) return;

        c.getTokens(); if (__ESBMC_reverted()) return;

        uint256 balAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blackAfter = c.blacklist(address(this)); if (__ESBMC_reverted()) return;

        assert(balAfter == balBefore + v && blackAfter);
    }

    receive() external payable {}
}

